            if (IsActiveThreadTerminating()) return _Fail_Val.Return();
            while (!IsDistanceBetweenThingsUnder(Game->GetHero(),Me,4.0f)) {
                Game->NewScriptFrame();
                if (IsActiveThreadTerminating()) return _Fail_Val.Return();
            }
            if (IsActiveThreadTerminating()) return _Fail_Val.Return();
            if (Game->GetHealth(Me)>0.0f) {
