                        if (IsActiveThreadTerminating()) return _Fail_Val.Return();
                    }
                    if (IsActiveThreadTerminating()) return _Fail_Val.Return();
                    Game->Pause(1.0f);
                    Game->EntitySetAsDamageable(Me,true);
                    Game->EntitySetAsKillable(Me,true,true);
