    if (IsActiveThreadTerminating()) return _Fail_Val.Return();
    if (ParentClass.CurrentStage==4) {
        if (IsActiveThreadTerminating()) return _Fail_Val.Return();
        std::vector<CScriptThing,std::allocator<CScriptThing> > Minions;
