        if (IsActiveThreadTerminating()) return _Fail_Val.Return();
    }
    if (IsActiveThreadTerminating()) return _Fail_Val.Return();
    if (!ParentClass.BanditSwitchAllegienceComplete) {
        if (IsActiveThreadTerminating()) return _Fail_Val.Return();
        long conversation = Game->AddNewConversation(Me, false, false);
